# List today's agent transcripts (mtime today) and extract user/assistant summaries
python3 - <<'PY'
import os,json,datetime
from pathlib import Path
root=Path("/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts")
# also memory mirrors
mirrors=Path.home()/".dc-platform/memory/mirrors/agent-transcripts"
day=datetime.date(2026,11,27)
items=[]
for base in [root, mirrors]:
    if not base.exists():
        continue
    for p in base.rglob("*.jsonl"):
        try:
            st=p.stat()
        except: continue
        mtime=datetime.datetime.fromtimestamp(st.st_mtime).date()
        # also check path date dirs
        if mtime!=day and day.isoformat() not in str(p):
            # still include if file content has today's date in first/last lines - check mtime within day window loosely
            if mtime < day - datetime.timedelta(days=1) or mtime > day:
                continue
        items.append((mtime, st.st_mtime, p))
# unique by name
seen=set(); uniq=[]
for mtime, mt, p in sorted(items, key=lambda x:-x[1]):
    key=p.name
    if key in seen: continue
    seen.add(key)
    uniq.append(p)
print(f"transcript files candidate: {len(uniq)}")
for p in uniq[:40]:
    users=[]; asst_tail=[]
    try:
        lines=p.read_text(errors='ignore').splitlines()
    except Exception as e:
        print(p, e); continue
    for line in lines:
        try: o=json.loads(line)
        except: continue
        role=o.get("role") or o.get("type") or ""
        # cursor format varies
        msg=o.get("message") or o
        r=msg.get("role") if isinstance(msg,dict) else role
        content=msg.get("content") if isinstance(msg,dict) else o.get("content")
        text=""
        if isinstance(content,str): text=content
        elif isinstance(content,list):
            parts=[]
            for c in content:
                if isinstance(c,dict) and c.get("type")=="text": parts.append(c.get("text",""))
                elif isinstance(c,str): parts.append(c)
            text="\n".join(parts)
        elif isinstance(content,dict):
            text=str(content.get("text") or content)[:500]
        if not text: continue
        if r=="user":
            # skip system wake noise somewhat but keep
            users.append(text.replace("\n"," ")[:180])
        elif r=="assistant":
            asst_tail.append(text.replace("\n"," ")[:160])
    print("---")
    print(p)
    print(f"users={len(users)} asst={len(asst_tail)}")
    for u in users[:8]:
        print("U:", u[:170])
    if asst_tail:
        print("A_last:", asst_tail[-1][:170])
